using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: Discriminator property renamed to "$type" in EF Core 9.
        // Preserve old property name so existing documents remain queryable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id no longer contains discriminator prefix ("Blog|1" → "1").
        // Preserve old format so existing documents with "Blog|1" ids remain accessible.
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // Breaking change: HasIndex now throws for Cosmos DB entities.
        // Removed — manage indexing via Azure Portal or Bicep/Terraform.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

